export const SYMBOLS = TABLE.map((r) => r[0]);
const INDEX = new Map(TABLE.map((r, i) => [r[0], i]));

/** True if `sym` is an element symbol with exact capitalisation ("Cl", not "CL"). */
export function isElement(sym) {
  return INDEX.has(sym);
}

/** Normalise user input such as "cl" to "Cl"; returns null if it is not an element. */
export function normalizeSymbol(text) {
  const t = String(text).trim();
  const sym = t.charAt(0).toUpperCase() + t.slice(1).toLowerCase();
  return INDEX.has(sym) ? sym : null;
}

export function atomicNumber(sym) {
  const i = INDEX.get(sym);
  return i === undefined ? 0 : i + 1;
}

export function covalentRadius(sym) {
  const i = INDEX.get(sym);
  return i === undefined ? 1.5 : TABLE[i][1];
}

export function color(sym) {
  const i = INDEX.get(sym);
  return i === undefined ? "#e07ad0" : TABLE[i][2];
}

/** Typical bond length used when placing a new atom (refined by optimization). */
export function bondLength(a, b) {
  return covalentRadius(a) + covalentRadius(b);
}
